1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// Context is a validated map of attribute names to string values.
74	type Context struct {
75		values map[string]string
76	}
77	
78	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
79	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
80	func LoadConfig(path string) (*Config, error) {
81		raw, err := os.ReadFile(path)
82		if err != nil {
83			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
84		}
85		return ParseConfig(raw)
86	}
87	
88	// LoadContext reads and validates a UTF-8 JSON context file.
89	func LoadContext(path string) (*Context, error) {
90		raw, err := os.ReadFile(path)
91		if err != nil {
92			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
93		}
94		return ParseContext(raw)
95	}
96	
97	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
98	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
99	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
100	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
101	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
102	// 类型检查以所属字段的类型错误报告。
103	func unmarshalStrictJSON(raw []byte) (any, error) {
104		dec := json.NewDecoder(bytes.NewReader(raw))
105		dec.UseNumber()
106		var doc any
107		if err := dec.Decode(&doc); err != nil {
108			return nil, err
109		}
110		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
111		offset := int(dec.InputOffset())
112		var extra any
113		if err := dec.Decode(&extra); err != io.EOF {
114			if err != nil {
115				return nil, err
116			}
117			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
118				offset++
119			}
120			c := byte(0)
121			if offset < len(raw) {
122				c = raw[offset]
123			}
124			return nil, fmt.Errorf("invalid character %q after top-level value", c)
125		}
126		return doc, nil
127	}
128	
129	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
130	func isJSONWhitespace(b byte) bool {
131		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
132	}
133	
134	// ParseConfig parses a config document from JSON bytes with strict typing.
135	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
136	func ParseConfig(raw []byte) (*Config, error) {
137		if !utf8.Valid(raw) {
138			return nil, fmt.Errorf("config: file is not valid UTF-8")
139		}
140		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
141			return nil, err
142		}
143		if err := rejectDuplicateFields(raw, "config"); err != nil {
144			return nil, err
145		}
146		doc, err := unmarshalStrictJSON(raw)
147		if err != nil {
148			return nil, fmt.Errorf("config: invalid JSON: %w", err)
149		}
150		root, ok := doc.(map[string]any)
151		if !ok {
152			return nil, fmt.Errorf("config: top level must be a JSON object")
153		}
154		flagsRaw, present := root["flags"]
155		if !present {
156			return nil, fmt.Errorf("config.flags: field is required")
157		}
158		if flagsRaw == nil {
159			return nil, fmt.Errorf("config.flags: must be an array, got null")
160		}
161		flagsArr, ok := flagsRaw.([]any)
162		if !ok {
163			return nil, fmt.Errorf("config.flags: must be an array")
164		}
165		cfg := &Config{}
166		seenKeys := map[string]int{}
167		for i, fr := range flagsArr {
168			flag, err := parseFlag(fr, i)
169			if err != nil {
170				return nil, err
171			}
172			if prev, dup := seenKeys[flag.Key]; dup {
173				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
174			}
175			seenKeys[flag.Key] = i
176			cfg.Flags = append(cfg.Flags, flag)
177		}
178		return cfg, nil
179	}
180	
181	// ParseContext parses an attribute-name -> string context object; it may be empty.
182	func ParseContext(raw []byte) (*Context, error) {
183		if !utf8.Valid(raw) {
184			return nil, fmt.Errorf("context: file is not valid UTF-8")
185		}
186		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
187			return nil, err
188		}
189		if err := rejectDuplicateFields(raw, "context"); err != nil {
190			return nil, err
191		}
192		doc, err := unmarshalStrictJSON(raw)
193		if err != nil {
194			return nil, fmt.Errorf("context: invalid JSON: %w", err)
195		}
196		root, ok := doc.(map[string]any)
197		if !ok {
198			return nil, fmt.Errorf("context: top level must be a JSON object")
199		}
200		// 值类型必须按原文顺序逐个判定：Go map 的遍历顺序不稳定，不能直接
201		// range root，否则同一文件在不同运行中可能报告不同属性。对象或数组
202		// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
203		if err := checkContextValueTypes(raw); err != nil {
204			return nil, err
205		}
206		ctx := &Context{values: make(map[string]string, len(root))}
207		for k, v := range root {
208			// 经过 checkContextValueTypes 后所有值都是字符串；数字（含超出浮点
209			// 范围的 json.Number）、布尔、null、对象、数组都已按所属属性报错。
210			ctx.values[k] = v.(string)
211		}
212		return ctx, nil
213	}
214	
215	// checkContextValueTypes 按文件原文顺序扫描已通过语法与重复字段检查的
216	// context 对象，报告第一个值不是字符串的顶层属性。键名使用解码后的文字
217	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。嵌套
218	// 对象或数组整体跳过，其内部成员不单独检查。
219	func checkContextValueTypes(raw []byte) error {
220		dec := json.NewDecoder(bytes.NewReader(raw))
221		// UseNumber：数字按 json.Number 原样保留而不转 float64，使超出浮点范围
222		// 的合法数字（如 1e400）也能落到“值必须是字符串”的属性类型错误，而不是
223		// 在解码阶段被报成 JSON 语法问题。
224		dec.UseNumber()
225		// 第一个令牌必须是顶层对象的 '{'；非对象的情形在 ParseContext 中报告。
226		if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
227			return nil
228		}
229		for dec.More() {
230			keyTok, err := dec.Token()
231			if err != nil {
232				return nil // 语法错误留给严格解码的报错
233			}
234			key, _ := keyTok.(string)
235			var value any
236			if err := dec.Decode(&value); err != nil {
237				return nil // 语法错误留给严格解码的报错
238			}
239			if _, ok := value.(string); !ok {
240				return fmt.Errorf("context.%s: value must be a string", key)
241			}
242		}
243		return nil
244	}
245	
246	// Get looks up an attribute; an empty string is a legal value.
247	func (c *Context) Get(attribute string) (string, bool) {
248		if c == nil {
249			return "", false
250		}
251		v, ok := c.values[attribute]
252		return v, ok
253	}
254	
255	// Find returns the flag with the given key, or nil if absent.
256	func (c *Config) Find(key string) *Flag {
257		if c == nil {
258			return nil
259		}
260		for i := range c.Flags {
261			if c.Flags[i].Key == key {
262				return &c.Flags[i]
263			}
264		}
265		return nil
266	}
267	
268	// Evaluate deterministically evaluates a flag against a context.
269	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
270	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
271	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
272	func (f *Flag) Evaluate(ctx *Context) EvalResult {
273		if !f.Enabled {
274			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
275		}
276		for i := range f.Rules {
277			rule := &f.Rules[i]
278			if rule.matches(ctx) {
279				id := rule.ID
280				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
281			}
282		}
283		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
284	}
285	
286	func (r *Rule) matches(ctx *Context) bool {
287		for i := range r.Conditions {
288			if !r.Conditions[i].matches(ctx) {
289				return false
290			}
291		}
292		return true
293	}
294	
295	func (c Condition) matches(ctx *Context) bool {
296		v, present := ctx.Get(c.Attribute)
297		if !present {
298			return false
299		}
300		switch c.Op {
301		case "eq":
302			return v == c.strVal
303		case "in":
304			for _, candidate := range c.inVal {
305				if v == candidate {
306					return true
307				}
308			}
309			return false
310		default:
311			// 解析阶段已拒绝未知运算符，防御性处理。
312			return false
313		}
314	}
315	
316	// MarshalResult renders the result as a single compact JSON object.
317	func MarshalResult(r EvalResult) ([]byte, error) {
318		var buf bytes.Buffer
319		enc := json.NewEncoder(&buf)
320		enc.SetEscapeHTML(false)
321		if err := enc.Encode(r); err != nil {
322			return nil, err
323		}
324		return bytes.TrimRight(buf.Bytes(), "\n"), nil
325	}
326	
327	// --- strict parsing helpers -------------------------------------------------
328	
329	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
330	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
331	type jsonFrame struct {
332		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
333		object bool
334		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
335		// Unicode 遍历不登记字段，保持 nil。
336		keys map[string]struct{}
337		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
338		lastKey string
339		// expectKey 标记对象内下一个字符串是否为字段名。
340		expectKey bool
341		// nextIndex 是数组下一个元素的下标。
342		nextIndex int
343	}
344	
345	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
346	// label 是根容器的位置前缀（"config" 或 "context"）。
347	type jsonPathTracker struct {
348		label string
349		stack []*jsonFrame
350	}
351	
352	func newJSONPathTracker(label string) *jsonPathTracker {
353		return &jsonPathTracker{label: label}
354	}
355	
356	func (t *jsonPathTracker) top() *jsonFrame {
357		return t.stack[len(t.stack)-1]
358	}
359	
360	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值用 .字段名，
361	// 数组元素用 [下标]。
362	func (t *jsonPathTracker) childPath() string {
363		top := t.top()
364		if top.object {
365			return top.path + "." + top.lastKey
366		}
367		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
368	}
369	
370	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
371	func (t *jsonPathTracker) beginContainer(object bool) string {
372		path := t.label
373		if len(t.stack) > 0 {
374			path = t.childPath()
375		}
376		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
377		return path
378	}
379	
380	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
381	// 一个已完成的值。
382	func (t *jsonPathTracker) endContainer() {
383		if len(t.stack) > 0 {
384			t.stack = t.stack[:len(t.stack)-1]
385		}
386		t.endValue()
387	}
388	
389	// atKey 报告下一个字符串是否应按对象字段名处理。
390	func (t *jsonPathTracker) atKey() bool {
391		return len(t.stack) > 0 && t.top().object && t.top().expectKey
392	}
393	
394	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
395	// 栈为空时返回根标签。
396	func (t *jsonPathTracker) currentPath() string {
397		if len(t.stack) == 0 {
398			return t.label
399		}
400		return t.top().path
401	}
402	
403	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
404	func (t *jsonPathTracker) valuePath() string {
405		if len(t.stack) == 0 {
406			return t.label
407		}
408		return t.childPath()
409	}
410	
411	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
412	// 数组推进元素下标。
413	func (t *jsonPathTracker) endValue() {
414		if len(t.stack) == 0 {
415			return
416		}
417		top := t.top()
418		if top.object {
419			top.expectKey = true
420		} else {
421			top.nextIndex++
422		}
423	}
424	
425	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
426	// 声明同名字段时返回重复字段错误。
427	func (t *jsonPathTracker) noteKey(name string) error {
428		top := t.top()
429		if top.keys == nil {
430			top.keys = make(map[string]struct{})
431		}
432		if _, dup := top.keys[name]; dup {
433			return fmt.Errorf("%s.%s: duplicate field %q", top.path, name, name)
434		}
435		top.keys[name] = struct{}{}
436		top.lastKey = name
437		top.expectKey = false
438		return nil
439	}
440	
441	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
442	// 仅维护字段值路径所需的状态。
443	func (t *jsonPathTracker) setKey(name string) {
444		top := t.top()
445		top.lastKey = name
446		top.expectKey = false
447	}
448	
449	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
450	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
451	func (t *jsonPathTracker) noteInvalidKey() {
452		t.top().expectKey = false
453	}
454	
455	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
456	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
457	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
458	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
459	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
460	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
461	// 留给严格 JSON 解码。
462	func rejectDuplicateFields(raw []byte, label string) error {
463		dec := json.NewDecoder(bytes.NewReader(raw))
464		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
465		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
466		dec.UseNumber()
467		tracker := newJSONPathTracker(label)
468		for {
469			tok, err := dec.Token()
470			if err != nil {
471				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
472				break
473			}
474			switch t := tok.(type) {
475			case json.Delim:
476				switch t {
477				case '{':
478					tracker.beginContainer(true)
479				case '[':
480					tracker.beginContainer(false)
481				case '}', ']':
482					tracker.endContainer()
483				}
484			case string:
485				if tracker.atKey() {
486					if err := tracker.noteKey(t); err != nil {
487						return err
488					}
489				} else {
490					tracker.endValue()
491				}
492			default:
493				tracker.endValue()
494			}
495		}
496		return nil
497	}
498	
499	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
500	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
501	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
502	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
503	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
504	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
505	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
506	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
507	// Unmarshal。
508	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
509		tracker := newJSONPathTracker(label)
510		i := 0
511		for i < len(raw) {
512			c := raw[i]
513			switch {
514			case c == '{' || c == '[':
515				tracker.beginContainer(c == '{')
516				i++
517			case c == '}' || c == ']':
518				tracker.endContainer()
519				i++
520			case c == '"':
521				end := jsonStringEnd(raw, i)
522				contentEnd := end
523				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
524					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
525				}
526				content := raw[i+1 : contentEnd]
527				if tracker.atKey() {
528					if bad := findBadUnicodeEscape(content); bad != nil {
529						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
530							tracker.currentPath(), string(content), bad.escape, bad.detail)
531					}
532					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
533					if name, ok := decodeJSONString(raw[i:end]); ok {
534						tracker.setKey(name)
535					} else {
536						tracker.noteInvalidKey()
537					}
538				} else {
539					path := tracker.valuePath()
540					if bad := findBadUnicodeEscape(content); bad != nil {
541						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
542							path, bad.escape, bad.detail)
543					}
544					tracker.endValue()
545				}
546				i = end
547			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
548				i++
549			default:
550				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
551				for i < len(raw) && !isJSONStructural(raw[i]) {
552					i++
553				}
554				tracker.endValue()
555			}
556		}
557		return nil
558	}
559	
560	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
561	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
562	func decodeJSONString(lit []byte) (s string, ok bool) {
563		if err := json.Unmarshal(lit, &s); err != nil {
564			return "", false
565		}
566		return s, true
567	}
568	
569	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
570	type badEscape struct {
571		escape string // 原文中的转义序列，如 \uD800
572		detail string // 具体问题（孤立高代理项/孤立低代理项）
573	}
574	
575	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
576	// （右引号之后的下标）；未终止时返回 len(raw)。
577	func jsonStringEnd(raw []byte, i int) int {
578		j := i + 1
579		for j < len(raw) {
580			switch raw[j] {
581			case '\\':
582				j += 2
583			case '"':
584				return j + 1
585			default:
586				j++
587			}
588		}
589		return len(raw)
590	}
591	
592	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
593	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
594	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
595	// 语法错误，不在此报告。
596	func findBadUnicodeEscape(content []byte) *badEscape {
597		j := 0
598		for j < len(content) {
599			if content[j] != '\\' {
600				j++
601				continue
602			}
603			if j+1 >= len(content) {
604				break
605			}
606			if content[j+1] != 'u' {
607				j += 2
608				continue
609			}
610			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
611				j += 2
612				continue
613			}
614			cp := hexVal4(content[j+2 : j+6])
615			switch {
616			case cp >= 0xD800 && cp <= 0xDBFF:
617				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
618				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
619					isHex4(content[j+8:j+12]) {
620					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
621						j += 12
622						continue
623					}
624				}
625				return &badEscape{
626					escape: string(content[j : j+6]),
627					detail: "high surrogate is not followed by a low surrogate",
628				}
629			case cp >= 0xDC00 && cp <= 0xDFFF:
630				return &badEscape{
631					escape: string(content[j : j+6]),
632					detail: "low surrogate is not preceded by a high surrogate",
633				}
634			}
635			j += 6
636		}
637		return nil
638	}
639	
640	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
641	func isJSONStructural(b byte) bool {
642		switch b {
643		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
644			return true
645		}
646		return false
647	}
648	
649	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
650	func isHex4(b []byte) bool {
651		if len(b) != 4 {
652			return false
653		}
654		for _, c := range b {
655			if !isHexDigit(c) {
656				return false
657			}
658		}
659		return true
660	}
661	
662	func isHexDigit(c byte) bool {
663		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
664	}
665	
666	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
667	func hexVal4(b []byte) int {
668		v := 0
669		for _, c := range b {
670			v <<= 4
671			switch {
672			case '0' <= c && c <= '9':
673				v |= int(c - '0')
674			case 'a' <= c && c <= 'f':
675				v |= int(c-'a') + 10
676			default: // 'A' <= c && c <= 'F'
677				v |= int(c-'A') + 10
678			}
679		}
680		return v
681	}
682	
683	func parseFlag(raw any, index int) (Flag, error) {
684		loc := fmt.Sprintf("config.flags[%d]", index)
685		obj, ok := raw.(map[string]any)
686		if !ok {
687			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
688		}
689		key, err := requireNonEmptyString(obj, "key", loc)
690		if err != nil {
691			return Flag{}, err
692		}
693		enabled, err := requireBool(obj, "enabled", loc)
694		if err != nil {
695			return Flag{}, err
696		}
697		def, err := requireBool(obj, "default", loc)
698		if err != nil {
699			return Flag{}, err
700		}
701		rulesArr, err := requireArrayField(obj, "rules", loc)
702		if err != nil {
703			return Flag{}, err
704		}
705		flag := Flag{Key: key, Enabled: enabled, Default: def}
706		seenRules := map[string]int{}
707		for ri, rv := range rulesArr {
708			rule, err := parseRule(rv, index, ri)
709			if err != nil {
710				return Flag{}, err
711			}
712			if prev, dup := seenRules[rule.ID]; dup {
713				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
714			}
715			seenRules[rule.ID] = ri
716			flag.Rules = append(flag.Rules, rule)
717		}
718		return flag, nil
719	}
720	
721	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
722		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
723		obj, ok := raw.(map[string]any)
724		if !ok {
725			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
726		}
727		id, err := requireNonEmptyString(obj, "id", loc)
728		if err != nil {
729			return Rule{}, err
730		}
731		value, err := requireBool(obj, "value", loc)
732		if err != nil {
733			return Rule{}, err
734		}
735		condsArr, err := requireArrayField(obj, "conditions", loc)
736		if err != nil {
737			return Rule{}, err
738		}
739		if len(condsArr) == 0 {
740			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
741		}
742		rule := Rule{ID: id, Value: value}
743		for ci, cv := range condsArr {
744			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
745			if err != nil {
746				return Rule{}, err
747			}
748			rule.Conditions = append(rule.Conditions, cond)
749		}
750		return rule, nil
751	}
752	
753	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
754		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
755		obj, ok := raw.(map[string]any)
756		if !ok {
757			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
758		}
759		attribute, err := requireNonEmptyString(obj, "attribute", loc)
760		if err != nil {
761			return Condition{}, err
762		}
763		op, err := requireNonEmptyString(obj, "op", loc)
764		if err != nil {
765			return Condition{}, err
766		}
767		valueField, err := requireField(obj, "value", loc)
768		if err != nil {
769			return Condition{}, err
770		}
771		cond := Condition{Attribute: attribute, Op: op}
772		switch op {
773		case "eq":
774			s, ok := valueField.(string)
775			if !ok {
776				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
777			}
778			cond.strVal = s
779		case "in":
780			arr, ok := valueField.([]any)
781			if !ok {
782				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
783			}
784			if len(arr) == 0 {
785				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
786			}
787			for ii, item := range arr {
788				s, ok := item.(string)
789				if !ok {
790					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
791				}
792				cond.inVal = append(cond.inVal, s)
793			}
794		default:
795			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
796		}
797		return cond, nil
798	}
799	
800	func requireField(obj map[string]any, name, loc string) (any, error) {
801		v, ok := obj[name]
802		if !ok {
803			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
804		}
805		if v == nil {
806			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
807		}
808		return v, nil
809	}
810	
811	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
812		v, err := requireField(obj, name, loc)
813		if err != nil {
814			return nil, err
815		}
816		arr, ok := v.([]any)
817		if !ok {
818			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
819		}
820		return arr, nil
821	}
822	
823	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
824		v, err := requireField(obj, name, loc)
825		if err != nil {
826			return "", err
827		}
828		s, ok := v.(string)
829		if !ok {
830			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
831		}
832		if s == "" {
833			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
834		}
835		return s, nil
836	}
837	
838	func requireBool(obj map[string]any, name, loc string) (bool, error) {
839		v, err := requireField(obj, name, loc)
840		if err != nil {
841			return false, err
842		}
843		b, ok := v.(bool)
844		if !ok {
845			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
846		}
847		return b, nil
848	}
