584	func TestQuotedBigNumberStaysString(t *testing.T) {
585		hugeInt := "1" + strings.Repeat("0", 400)
586		// 同样的数字文本加上引号后就是普通字符串，按原文参与 eq 匹配，
587		// 不能被数值化、改写或继续拒绝。
588		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
589			{"id":"r-exp","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"1e400"}]},
590			{"id":"r-neg","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"-1e400"}]},
591			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
592		for _, tc := range []struct {
593			ctxRaw string
594			ruleID string
595			reason EvalReason
596		}{
597			{`{"plan":"1e400"}`, "r-exp", EvalRule},
598			{`{"plan":"-1e400"}`, "r-neg", EvalRule},
599			{`{"plan":"` + hugeInt + `"}`, "r-int", EvalRule},
600			{`{"plan":"1e401"}`, "", EvalDefault}, // 不做数值换算："1e401" != "1e400"
601		} {
602			got := eval(t, cfg, "f", tc.ctxRaw)
603			if got.Reason != tc.reason ||
604				(tc.reason == EvalRule && (got.RuleID == nil || *got.RuleID != tc.ruleID)) {
605				t.Fatalf("ctx=%s: got %+v, want reason=%s rule=%s", tc.ctxRaw, got, tc.reason, tc.ruleID)
