610		cfgInt := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
611			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
612		if got := eval(t, cfgInt, "g", `{"plan":"1e400"}`); got.Reason != EvalDefault {
613			t.Fatalf("numerically equal spellings must not match as strings: %+v", got)
614		}
