616			t.Fatalf("identical spelling must match verbatim: %+v", got)
617		}
618	
619		// ParseContext 保留引号内的原文，不做任何转换。
620		ctx := mustParseContext(t, `{"plan":"1e400"}`)
621		if v, ok := ctx.Get("plan"); !ok || v != "1e400" {
622			t.Fatalf("quoted big number was rewritten: %q %v", v, ok)
623		}
624	}
