875			t.Fatalf("literal U+FFFD still matches: %+v", got)
876		}
877		// 字段名被替换后也不能误报重复字段："\uD800x" 与 "�x" 本不应同名，
878		// 但非法转义必须先于重复字段检查以自身名义报错。
879		_, err := ParseContext([]byte(`{"\uD800x":"a","�x":"b"}`))
880		if err == nil || strings.Contains(err.Error(), "duplicate field") {
881			t.Fatalf("lone surrogate in field name must not surface as duplicate field: %v", err)
882		}
883	}
884	
885	func TestValidUnicodeEscapesUnchanged(t *testing.T) {
886		// 正确配对的代理项转义与直接写出的同一字符按同一字符串比较。
887		// emojiEsc 是 "😀" 的代理项对转义形式（分两段书写仅为避免源码层面的转义歧义）。
888		emojiEsc := `\uD83D` + `\uDE00`
889		cfgEsc := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
890			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"` + emojiEsc + `"}]}]}]}`
891		if got := eval(t, cfgEsc, "f", `{"emoji":"😀"}`); got.Reason != EvalRule {
892			t.Fatalf("paired escape equals literal: %+v", got)
893		}
894		cfgLit := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
895			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"😀"}]}]}]}`
896		if got := eval(t, cfgLit, "f", `{"emoji":"`+emojiEsc+`"}`); got.Reason != EvalRule {
897			t.Fatalf("literal equals paired escape: %+v", got)
898		}
899		// 真正的 "�" 与 "�" 仍是合法字符串，不能一概禁止替换字符。
900		mustParseContext(t, `{"a":"�","b":"\u`+`FFFD"}`)
901		if got := eval(t, cfgLit, "f", `{"emoji":"�"}`); got.Reason != EvalDefault {
902			t.Fatalf("U+FFFD is just another string: %+v", got)
903		}
904		// 反斜杠转义后的 "\uD800" 是普通文本（内容为 \uD800 六个字符）。
905		mustParseContext(t, `{"a":"\\uD800"}`)
906		cfgText := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
907			{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\\uD800"}]}]}]}`
908		if got := eval(t, cfgText, "f", `{"a":"\\uD800"}`); got.Reason != EvalRule {
909			t.Fatalf("escaped backslash text: %+v", got)
910		}
911	}
912	
913	func TestEmptyFlagListAndFind(t *testing.T) {
914		cfg := mustParseConfig(t, `{"flags":[]}`)
915		if cfg.Find("missing") != nil {
916			t.Error("expected nil flag")
917		}
918		var nilCfg *Config
919		if nilCfg.Find("x") != nil {
920			t.Error("nil config Find should be nil")
921		}
922		flag := (&Flag{Key: "f", Enabled: false})
923		if got := flag.Evaluate(nil); got.Reason != EvalDisabled {
924			t.Errorf("nil context on disabled flag: %+v", got)
925		}
926	}
