		{"context brackets not indices", `{"x[0]":1,"x[0]":2}`, `context["x[0]"]`},
		{"context escaped same as direct", `{"a.b":1,"\u0061.b":2}`, `context["a.b"]`},
		{"context newline name", "{\"li\\nne\":1,\"li\\nne\":2}", `context["li\nne"]`},
